  pen.fill(FIN);
  pen.poly([-14, 0, -28, -11, -28, 11]);
  pen.fill(BODY);
  pen.ellipse(0, 0, 20, 11);
  pen.fill("black");
  pen.circle(10, -3, 2);
}
