import { step } from "../world/movement.js";
import { wrap } from "../world/bounds.js";

// colours
const BODY = "#ffb6c1"; // light pink
const SPOT = "#ff69b4"; // deeper pink

export function spawn() {
  // start near bottom, facing up
  return {
    x: (Math.random() - 0.5) * 80,
    y: 40,
    vx: 0,
    vy: 0,
    kind: "seahorse",
  };
}

export function update(sea, world) {
  // bobbing motion using sine of age
  const bobSpeed = 0.5; // units per tick amplitude
  sea.vy = Math.sin(sea.age * 0.2) * bobSpeed;
  // apply movement
  step(sea);
  wrap(sea, world);
}

export function draw(sea, pen) {
  // draw a simple seahorse shape: vertical ellipse with a small circle head
  pen.fill(BODY);
  pen.ellipse(sea.x, sea.y, 8, 20); // body
  pen.fill(SPOT);
  pen.circle(sea.x, sea.y - 10, 4); // head
}

export const count = 3;
